import json
p=json.load(open('.omgithub/conversation.json'))
for m in p['messages'][1:]:
 print('\n---',m.get('type'),m.get('agent'),m.get('id'), 'finish',m.get('finish'), 'err',m.get('error'))
 c=m.get('content')
 if isinstance(c,list):
  for x in c:
   if x.get('type') in ('text','reasoning'):
    print(x.get('type'),str(x.get('text',''))[:1000])
 elif c: print(str(c)[:3000])
